<?php declare( strict_types=1 ); namespace Inc\Repositories\WPDBRepositories; use Inc\DTO\Exam\ExamGuestSessionDTO; use Inc\Enums\Settings\TableName; class ExamGuestSessionRepository { private \wpdb $wpdb; private string $table; public function __construct( ?\wpdb $wpdb = null ) { $this->wpdb = $wpdb ?? $GLOBALS['wpdb']; $this->table = TableName::ExamGuestSessions->prefixed(); } public function insert( array $data ): int { $this->wpdb->insert( $this->table, $data ); return (int) $this->wpdb->insert_id; } public function find( int $id ): ?ExamGuestSessionDTO { $row = $this->wpdb->get_row( $this->wpdb->prepare( "SELECT * FROM %i WHERE id = %d", $this->table, $id ), ARRAY_A ); return $row ? ExamGuestSessionDTO::fromArray( $row ) : null; } public function findByCookieHash( string $cookieHash ): ?ExamGuestSessionDTO { $row = $this->wpdb->get_row( $this->wpdb->prepare( "SELECT * FROM %i WHERE cookie_hash = %s AND revoked_at IS NULL", $this->table, $cookieHash ), ARRAY_A ); return $row ? ExamGuestSessionDTO::fromArray( $row ) : null; } public function update( int $id, array $data ): bool { return false !== $this->wpdb->update( $this->table, $data, [ 'id' => $id ] ); } }
